}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = (fragCoord - 0.5 * iResolution.xy) / iResolution.y * 2.0;
    const float TWO_PI = 6.28318530718;

    float secN = mod(iTime, 60.0);
    float minN = mod(iTime / 60.0, 60.0);
    float hourN = mod(iTime / 3600.0, 12.0);
    float thetaSec = secN / 60.0 * TWO_PI;
    float thetaMin = (minN + secN / 60.0) / 60.0 * TWO_PI;
    float thetaHour = (hourN + minN / 60.0) / 12.0 * TWO_PI;

    float v = voronoi(uv * 4.0);
    vec3 cellCol = mix(vec3(0.05, 0.05, 0.1), vec3(0.5, 0.55, 0.65), v);

    float rFace = length(uv);
    float faceMask = smoothstep(0.95, 0.9, rFace);
    vec3 col = mix(vec3(0.0), cellCol, faceMask);

    float ring = smoothstep(0.025, 0.0, abs(rFace - 0.9));
    col = mix(col, vec3(0.95), ring);

    for (int i = 0; i < 12; i++) {
        float a = float(i) / 12.0 * TWO_PI;
        vec2 dir = vec2(sin(a), cos(a));
        float tick = smoothstep(0.03, 0.0, length(uv - dir * 0.8));
        col = mix(col, vec3(1.0), tick);
    }

    vec2 hourDir = vec2(sin(thetaHour), cos(thetaHour));
    vec2 minDir = vec2(sin(thetaMin), cos(thetaMin));
    vec2 secDir = vec2(sin(thetaSec), cos(thetaSec));

    float dHour = sdSegment(uv, vec2(0.0), hourDir * 0.45);
    float dMin = sdSegment(uv, vec2(0.0), minDir * 0.65);
    float dSec = sdSegment(uv, vec2(0.0), secDir * 0.78);

    col = mix(col, vec3(0.05), smoothstep(0.024, 0.01, dHour));
    col = mix(col, vec3(0.05), smoothstep(0.017, 0.008, dMin));
    col = mix(col, vec3(1.0, 0.3, 0.15), smoothstep(0.012, 0.004, dSec));

    float hub = smoothstep(0.03, 0.02, rFace);
    col = mix(col, vec3(1.0, 0.3, 0.15), hub);

    fragColor = vec4(clamp(col, 0.0, 1.0), 1.0);
}

float hash21(vec2 p) {
    p = fract(p * vec2(123.34, 456.21));
    p += dot(p, p + 45.32);
    return fract(p.x * p.y);
}

float sdCircle(vec2 p, float r) {
    return length(p) - r;
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 res = iResolution.xy;
    vec2 uv = fragCoord.xy / res;
    float aspect = res.x / res.y;
    vec2 p = uv;
    p.x *= aspect;

    vec3 sky = mix(vec3(0.05, 0.07, 0.15), vec3(0.35, 0.4, 0.55), uv.y);
    vec3 col = sky;

    float growth = clamp(iTime * 0.04, 0.0, 0.3);
    float pile = 1e5;
    for (int i = 0; i < 8; i++) {
        float fi = float(i);
        float cx = (fi + 0.5) / 8.0 * aspect;
        float rnd = hash21(vec2(fi, 1.0));
        float r = 0.09 + 0.05 * rnd + growth * 0.5;
        vec2 center = vec2(cx, 0.02);
        float d = sdCircle(p - center, r);
        pile = min(pile, d);
    }
    float pileMask = 1.0 - smoothstep(-0.01, 0.01, pile);

    float snow = 0.0;
    for (int i = 0; i < 5; i++) {
        float fi = float(i);
        float speed = 0.06 + fi * 0.025;
        float scale = 8.0 + fi * 5.0;
        vec2 gv = p * scale;
        gv.y += iTime * speed * 12.0 + fi * 17.3;
        vec2 id = floor(gv);
        vec2 f = fract(gv) - 0.5;
        vec2 jitter = vec2(hash21(id + fi), hash21(id + fi + 3.3)) - 0.5;
        float size = 0.06 + 0.05 * hash21(id + fi + 7.1);
        float d = length(f - jitter * 0.7);
        float flake = 1.0 - smoothstep(size * 0.2, size, d);
        snow += flake * (1.0 - fi * 0.15);
    }
    col += vec3(snow) * 0.9;
    col = mix(col, vec3(0.95, 0.97, 1.0), pileMask);

    fragColor = vec4(clamp(col, 0.0, 1.0), 1.0);
}

float hash21(vec2 p) {
    p = fract(p * vec2(123.34, 456.21));
    p += dot(p, p + 45.32);
    return fract(p.x * p.y);
}

float noise(vec2 p) {
    vec2 i = floor(p);
    vec2 f = fract(p);
    f = f * f * (3.0 - 2.0 * f);
    float a = hash21(i);
    float b = hash21(i + vec2(1.0, 0.0));
    float c = hash21(i + vec2(0.0, 1.0));
    float d = hash21(i + vec2(1.0, 1.0));
    return mix(mix(a, b, f.x), mix(c, d, f.x), f.y);
}

float fbm(vec2 p) {
    float v = 0.0;
    float a = 0.5;
    for (int i = 0; i < 5; i++) {
        v += a * noise(p);
        p *= 2.0;
        a *= 0.5;
    }
    return v;
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 res = iResolution.xy;
    vec2 uv = fragCoord.xy / res;
    vec2 p = uv;
    p.x *= res.x / res.y;

    vec3 col = mix(vec3(0.06, 0.08, 0.16), vec3(0.5, 0.55, 0.65), uv.y * 0.8);

    float growth = clamp(iTime * 0.03, 0.0, 0.25);
    vec2 wp = vec2(p.x * 2.0, iTime * 0.05);
    vec2 warp = vec2(fbm(wp + 1.3), fbm(wp + 5.7));
    float ground = 0.1 + growth + 0.06 * fbm(p * 3.0 + warp * 1.5);
    float pileMask = 1.0 - smoothstep(ground - 0.015, ground + 0.015, p.y);

    vec2 wind = vec2(fbm(p * 1.5 + iTime * 0.1) - 0.5, 0.0) * 0.3;
    float snow = 0.0;
    for (int i = 0; i < 5; i++) {
        float fi = float(i);
        vec2 sp = p + wind * (fi + 1.0);
        sp *= 6.0 + fi * 5.0;
        sp.y += iTime * (0.5 + fi * 0.15) * 6.0;
        vec2 id = floor(sp);
        vec2 f = fract(sp) - 0.5;
        vec2 jitter = vec2(hash21(id + fi * 2.0), hash21(id + fi * 2.0 + 4.0)) - 0.5;
        float size = 0.05 + 0.04 * hash21(id + fi + 9.0);
        float d = length(f - jitter * 0.6);
        snow += (1.0 - smoothstep(size * 0.2, size, d)) * (1.0 - fi * 0.15);
    }
    col += vec3(snow) * 0.85;

    vec3 pileColor = vec3(0.93, 0.96, 1.0) * (0.9 + 0.1 * fbm(p * 8.0));
    col = mix(col, pileColor, pileMask);

    fragColor = vec4(clamp(col, 0.0, 1.0), 1.0);
}

float hash21(vec2 p) {
    p = fract(p * vec2(123.34, 456.21));
    p += dot(p, p + 45.32);
    return fract(p.x * p.y);
}

float noise(vec2 p) {
    vec2 i = floor(p);
    vec2 f = fract(p);
    f = f * f * (3.0 - 2.0 * f);
    float a = hash21(i);
    float b = hash21(i + vec2(1.0, 0.0));
    float c = hash21(i + vec2(0.0, 1.0));
    float d = hash21(i + vec2(1.0, 1.0));
    return mix(mix(a, b, f.x), mix(c, d, f.x), f.y);
}

float fbm(vec2 p) {
    float v = 0.0;
    float a = 0.5;
    for (int i = 0; i < 5; i++) {
        v += a * noise(p);
        p *= 2.0;
        a *= 0.5;
    }
    return v;
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = fragCoord.xy / iResolution.xy;
    vec2 p = uv;
    p.x *= iResolution.x / iResolution.y;

    vec3 col = mix(vec3(0.08, 0.09, 0.14), vec3(0.4, 0.45, 0.55), uv.y);

    float growth = clamp(iTime * 0.035, 0.0, 0.28);
    float h1 = fbm(vec2(p.x * 3.0, 0.0));
    float h2 = fbm(vec2(p.x * 7.0 + 5.0, 0.0));
    float ground = 0.09 + growth + h1 * 0.05 + h2 * 0.025;
    float pileMask = 1.0 - smoothstep(ground - 0.012, ground + 0.012, p.y);

    float snow = 0.0;
    for (int i = 0; i < 4; i++) {
        float fi = float(i);
        vec2 sp = p * (10.0 + fi * 6.0);
        sp.y += iTime * (0.4 + fi * 0.2) * 5.0;
        float n = fbm(sp);
        float layer = smoothstep(0.78 - fi * 0.03, 0.86, n);
        snow += layer * (1.0 - fi * 0.18);
    }
    col += vec3(snow) * 0.9;

    vec3 pileColor = vec3(0.92, 0.95, 1.0) * (0.88 + 0.12 * h2);
    col = mix(col, pileColor, pileMask);

    fragColor = vec4(clamp(col, 0.0, 1.0), 1.0);
}

